}

.hero__cta {
    background: linear-gradient(135deg, var(--accent-primary), #ff8a50);
    color: white;
    border: none;
    padding: 1rem 2.5rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 50px;
    cursor: pointer;
    transition: var(--transition);
    box-shadow: 0 10px 30px rgba(255, 107, 53, 0.3);
}

.hero__cta:hover {
