}

.article-card__title {
    font-size: 1.3rem;
    font-weight: 700;
    margin-bottom: 0.8rem;
    line-height: 1.3;
}

.article-card__excerpt {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    line-height: 1.6;
    flex-grow: 1;
}

.article-card__link {
    color: var(--accent-secondary);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
}

.article-card__link:hover {
    color: var(--accent-primary);
    gap: 0.5rem;
}

/* Newsletter Section */
.newsletter {
    background: linear-gradient(135deg, rgba(255, 107, 53, 0.1) 0%, rgba(78, 205, 196, 0.1) 100%);
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
    padding: 4rem 2rem;
}

.newsletter__container {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
}

.newsletter__title {
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.newsletter__subtitle {
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.newsletter__form {
    display: flex;
    gap: 0.5rem;
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 50px;
    padding: 0.5rem;
}

.newsletter__form input {
    flex: 1;
    background: none;
    border: none;
    color: var(--text-primary);
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    outline: none;
}

.newsletter__form input::placeholder {
    color: var(--text-secondary);
}

.newsletter__form button {
    background: linear-gradient(135deg, var(--accent-primary), #ff8a50);
    color: white;
    border: none;
    padding: 0.75rem 2rem;
    border-radius: 50px;
    cursor: pointer;
    font-weight: 600;
    transition: var(--transition);
}

.newsletter__form button:hover {
    transform: scale(1.02);
}

/* Footer */
.footer {
    background-color: var(--bg-secondary);
    border-top: 1px solid var(--border-color);
    padding: 4rem 2rem 2rem;
}

.footer__container {
    max-width: 1400px;
    margin: 0 auto;
}

.footer__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer__section {
    display: flex;
    flex-direction: column;
}

.footer__title {
    font-weight: 700;
    margin-bottom: 1rem;
}

.footer__links {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
}

.footer__links a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: var(--transition);
}

.footer__links a:hover {
    color: var(--accent-primary);
}

.footer__bottom {
    border-top: 1px solid var(--border-color);
    padding-top: 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

.footer__legal {
    display: flex;
    gap: 1rem;
    align-items: center;
}

.footer__legal a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: var(--transition);
}

.footer__legal a:hover {
    color: var(--accent-primary);
}

/* Responsive Design */
@media (max-width: 768px) {
    .navbar__container {
        flex-wrap: wrap;
        gap: 1rem;
    }

    .navbar__menu {
        order: 3;
        width: 100%;
        gap: 1rem;
        font-size: 0.9rem;
    }

    .hero__title {
        font-size: 2.5rem;
    }

    .hero__subtitle {
        font-size: 1.1rem;
    }

    .section__title {
        font-size: 2rem;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
        gap: 1.5rem;
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .footer__bottom {
        flex-direction: column;
        align-items: flex-start;
    }
}

@media (max-width: 480px) {
    .navbar__container {
        padding: 0.75rem 1rem;
    }

    .navbar__menu {
        display: none;
    }

    .hero {
        min-height: 400px;
        padding: 2rem 1rem;
    }

    .hero__title {
        font-size: 2rem;
    }

    .featured-products,
    .editorial,
    .deals {
        padding: 3rem 1rem;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .section__title {
        font-size: 1.5rem;
    }

    .deal-card {
        padding: 1.5rem;
    }

    .newsletter__form {
        flex-direction: column;
    }
}
