.product-card {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    border-color: var(--accent-primary);
    transform: translateY(-8px);
    box-shadow: 0 20px 50px rgba(255, 107, 53, 0.2);
}

.product-card__image {
    position: relative;
    background-color: var(--bg-tertiary);
    height: 250px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.product-card__placeholder {
    font-size: 5rem;
}

.product-card__badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: var(--accent-primary);
    color: white;
    padding: 0.4rem 0.8rem;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
}

.product-card__content {
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-card__name {
    font-size: 1.2rem;
    font-weight: 600;
    margin-bottom: 0.3rem;
}

.product-card__category {
    color: var(--text-secondary);
    font-size: 0.9rem;
    margin-bottom: 0.7rem;
}

.product-card__rating {
    color: var(--accent-tertiary);
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

.product-card__price {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 1rem;
    margin-top: auto;
}

.price__original {
    color: var(--text-secondary);
    text-decoration: line-through;
    font-size: 0.95rem;
}

.price__current {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--accent-primary);
}

.product-card__btn {
    background-color: var(--bg-tertiary);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
    padding: 0.8rem;
    border-radius: 8px;
    cursor: pointer;
    transition: var(--transition);
    font-weight: 600;
}

.product-card__btn:hover {
    background-color: var(--accent-primary);
    border-color: var(--accent-primary);
    color: white;
}

/* Deals Section */
.deals {
    background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
    padding: 6rem 2rem;
    border-top: 1px solid var(--border-color);
}

.deals__container {
    max-width: 1400px;
    margin: 0 auto;
}

.deals__header {
    text-align: center;
    margin-bottom: 4rem;
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

/* Deal Card */
.deal-card {
    border-radius: 12px;
    padding: 2.5rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    min-height: 320px;
    transition: var(--transition);
    border: 1px solid transparent;
}

.deal-card:hover {
    transform: translateY(-5px);
}

.deal-card--primary {
    background: linear-gradient(135deg, rgba(255, 107, 53, 0.15) 0%, rgba(255, 107, 53, 0.05) 100%);
    border-color: var(--accent-primary);
}

.deal-card--secondary {
    background: linear-gradient(135deg, rgba(78, 205, 196, 0.15) 0%, rgba(78, 205, 196, 0.05) 100%);
    border-color: var(--accent-secondary);
}

.deal-card--tertiary {
    background: linear-gradient(135deg, rgba(255, 215, 0, 0.15) 0%, rgba(255, 215, 0, 0.05) 100%);
    border-color: var(--accent-tertiary);
}

.deal-card__badge {
    display: inline-block;
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    margin-bottom: 1rem;
    padding: 0.5rem 1rem;
    border-radius: 20px;
    width: fit-content;
}

.deal-card--primary .deal-card__badge {
    background-color: rgba(255, 107, 53, 0.3);
    color: var(--accent-primary);
}

.deal-card--secondary .deal-card__badge {
    background-color: rgba(78, 205, 196, 0.3);
    color: var(--accent-secondary);
}

.deal-card--tertiary .deal-card__badge {
    background-color: rgba(255, 215, 0, 0.3);
    color: var(--accent-tertiary);
}

.deal-card__title {
    font-size: 1.8rem;
    font-weight: 700;
    margin-bottom: 0.8rem;
}

.deal-card__description {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    line-height: 1.5;
}

.deal-card__countdown {
    font-size: 0.9rem;
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    font-style: italic;
}

.deal-card__btn {
    background: none;
    border: 2px solid currentColor;
    color: var(--text-primary);
    padding: 0.8rem 1.5rem;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 600;
    transition: var(--transition);
}

.deal-card--primary .deal-card__btn {
    border-color: var(--accent-primary);
    color: var(--accent-primary);
}

.deal-card--primary .deal-card__btn:hover {
    background-color: var(--accent-primary);
    color: white;
}

.deal-card--secondary .deal-card__btn {
    border-color: var(--accent-secondary);
    color: var(--accent-secondary);
}

.deal-card--secondary .deal-card__btn:hover {
    background-color: var(--accent-secondary);
    color: white;
}

.deal-card--tertiary .deal-card__btn {
    border-color: var(--accent-tertiary);
    color: var(--accent-tertiary);
}

.deal-card--tertiary .deal-card__btn:hover {
    background-color: var(--accent-tertiary);
    color: var(--bg-primary);
}

/* Editorial Section */
.editorial {
    max-width: 1400px;
    margin: 0 auto;
    padding: 6rem 2rem;
}

.articles-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 2rem;
}

/* Article Card */
.article-card {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.article-card:hover {
    border-color: var(--accent-secondary);
    box-shadow: 0 20px 50px rgba(78, 205, 196, 0.1);
}

.article-card__image {
    position: relative;
    background-color: var(--bg-tertiary);
    height: 200px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.article-card__placeholder {
    font-size: 3rem;
}

.article-card__date {
    position: absolute;
    bottom: 1rem;
    left: 1rem;
    background-color: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(5px);
    padding: 0.4rem 0.8rem;
    border-radius: 20px;
    font-size: 0.8rem;
    color: var(--text-secondary);
}

.article-card__content {
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.article-card__category {
    display: inline-block;
    color: var(--accent-secondary);
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    margin-bottom: 0.8rem;
}

.article-card__title {
    font-size: 1.3rem;
    font-weight: 700;
    margin-bottom: 0.8rem;
    line-height: 1.3;
}

.article-card__excerpt {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    line-height: 1.6;
    flex-grow: 1;
}

.article-card__link {
    color: var(--accent-secondary);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
}

.article-card__link:hover {
    color: var(--accent-primary);
    gap: 0.5rem;
}

/* Newsletter Section */
.newsletter {
    background: linear-gradient(135deg, rgba(255, 107, 53, 0.1) 0%, rgba(78, 205, 196, 0.1) 100%);
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
    padding: 4rem 2rem;
}

.newsletter__container {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
}

.newsletter__title {
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.newsletter__subtitle {
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.newsletter__form {
    display: flex;
    gap: 0.5rem;
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 50px;
    padding: 0.5rem;
}

.newsletter__form input {
